SELECT COUNT(*) FROM customer as c, orders as o, lineitem as l, supplier as s, nation as n WHERE c.stream_part = 'R' AND o.stream_part = 'R' AND l.stream_part = 'R' AND s.stream_part = 'R' AND n.stream_part = 'R' AND  c.c_custkey = o.o_custkey AND l.l_orderkey = o.o_orderkey AND l.l_suppkey = s.s_suppkey AND c.c_nationkey = s.s_nationkey AND s.s_nationkey = n.n_nationkey AND c.c_mktsegment = 'BUILDING';
